// The twelve-scan timeline as the history commands answer it (generated by the core's own
// functions, see `crates/core/tests/mock_results.rs`), for the development mock and tests.
import type { ExpectedRule, HistoryView, Project, Report, ScanFact } from '@/api'

export interface ResultsBundle {
  projects: Project[]
  rules: ExpectedRule[]
  history: HistoryView
  /** The report of each scan, by scan number. */
  reports: Record<string, Report>
  facts: ScanFact[]
}

const ISO = /^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?Z$/

/** `value` with every RFC 3339 timestamp inside moved by `ms`. */
export function shiftTimes<T>(value: T, ms: number): T {
  if (typeof value === 'string') {
    return (ISO.test(value) ? new Date(Date.parse(value) + ms).toISOString() : value) as T
  }
  if (Array.isArray(value)) return value.map((v) => shiftTimes(v, ms)) as T
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, shiftTimes(v, ms)])) as T
  }
  return value
}

/** The bundle as if scan `upTo` were the latest and finished `agoMs` ago. */
export function bundleAsOf(bundle: ResultsBundle, upTo: number, agoMs: number, now = Date.now()) {
  const scans = bundle.history.scans.filter((s) => s.seq <= upTo)
  const last = scans[scans.length - 1]
  const shift = last ? now - agoMs - Date.parse(last.finished_at) : 0
  const reports: Record<string, Report> = {}
  for (const [seq, report] of Object.entries(bundle.reports)) {
    if (Number(seq) <= upTo) reports[seq] = shiftTimes(report, shift)
  }
  return {
    projects: bundle.projects,
    rules: shiftTimes(bundle.rules, 0),
    history: shiftTimes({ ...bundle.history, scans }, shift),
    reports,
    facts: shiftTimes(
      bundle.facts.filter((f) => f.seq <= upTo),
      shift,
    ),
    latest: upTo,
  }
}
